 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # The repeating template is the leftmost block ending at its full-height background border.
    border = next(c for c in range(1, w) if all(grid[r][c] == bg for r in range(h)))
    left = [row[:border + 1] for row in grid]

    def shape(cells):
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        return tuple(tuple((r, c) in cells for c in range(c0, c1 + 1)) for r in range(r0, r1 + 1))

    # Each framed region on the left encodes one silhouette; each colored object on the right supplies its color.
    objects = {}
    for color in sorted({v for row in grid for v in row if v not in (0, bg)}):
        cells = {(r, c) for r in range(h) for c in range(border + 1, w) if grid[r][c] == color}
        if cells:
            objects[shape(cells)] = color

    separators = [r for r, row in enumerate(left) if all(v == bg for v in row)]
    out = [row[:] for row in left]
    for a, b in zip(separators, separators[1:]):
        holes = {(r, c) for r in range(a + 1, b) for c in range(1, border)
                 if left[r][c] != bg}
        if not holes:
            continue
        sig = shape(holes)
        color = objects.get(sig)
        if color is not None:
            for r, c in holes:
                out[r][c] = color
    return out
